-- MarketHub comprehensive development/demo seed data
-- PostgreSQL 17 | Apply AFTER all Flyway migrations (currently V19).
-- Usage: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f backend/src/main/resources/db/demo-seed.sql
