-- Quick post-load inventory: every application table should now contain demo rows.
SELECT table_name
FROM information_schema.tables
WHERE table_schema = current_schema()
  AND table_type = 'BASE TABLE'
  AND table_name IN (
    'app_users','refresh_tokens','vendors','store_profiles','products','product_inventory',
    'inventory_adjustments','inventory_reservations','customer_carts','customer_cart_items',
    'customer_orders','vendor_orders','order_items','payments','transactional_outbox',
    'payment_provider_events','payment_reconciliation_attempts','payment_manual_resolutions',
    'vendor_order_status_history','vendor_order_shipments','customer_notifications',
    'product_reviews','product_review_moderation_events','admin_product_moderation_events',
    'admin_vendor_status_events'
  )
ORDER BY table_name;
